package com.mirigangneung.course.domain; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="courses") public class Course { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; private String title; private String durationType; private LocalDate startDate,endDate; private String shareTokenHash; private OffsetDateTime shareExpiresAt,createdAt,expiresAt; protected Course(){} public Course(String duration,LocalDate start,LocalDate end){durationType=duration;startDate=start;endDate=end;title="나만의 강릉 코스";createdAt=OffsetDateTime.now();} public UUID getId(){return id;}public String getTitle(){return title;}public String getDurationType(){return durationType;}public String getShareTokenHash(){return shareTokenHash;}public OffsetDateTime getShareExpiresAt(){return shareExpiresAt;}public void share(String hash,OffsetDateTime expires){shareTokenHash=hash;shareExpiresAt=expires;}public void revokeShare(){shareTokenHash=null;shareExpiresAt=null;}}
